import{_ as o,o as t,c as d,a0 as a}from"./chunks/framework.Bmhw_dvp.js";const h=JSON.parse('{"title":"视频源与 API 获取逻辑","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/video-pipeline.md","filePath":"advanced/video-pipeline.md","lastUpdated":1793354613000}'),i={name:"advanced/video-pipeline.md"};function s(r,e,l,c,n,u){return t(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="视频源与-api-获取逻辑" tabindex="-1">视频源与 API 获取逻辑 <a class="header-anchor" href="#视频源与-api-获取逻辑" aria-label="Permalink to &quot;视频源与 API 获取逻辑&quot;">​</a></h1><p>从「拿到 BV 号或直链」到「浏览器里播出来」的完整链路：B站解析、代理层、直链实时解析、播放引擎、字幕、弹幕、推流与下载。参数集中在文末常量表。</p><h2 id="bilibili-解析" tabindex="-1">Bilibili 解析 <a class="header-anchor" href="#bilibili-解析" aria-label="Permalink to &quot;Bilibili 解析&quot;">​</a></h2><h3 id="请求链路" tabindex="-1">请求链路 <a class="header-anchor" href="#请求链路" aria-label="Permalink to &quot;请求链路&quot;">​</a></h3><p>前端输入先规整成 BV 号，再依次补齐会话、权限与播放地址：</p><ol><li>提交 BV / AV 号、视频链接或 b23.tv 短链。短链只信任 <code>b23.tv</code> / <code>bili2233.cn</code>（精确匹配），GET 跟随重定向、8s 超时，成功后立即取消响应体释放连接。</li><li>用 <code>/BV[0-9A-Za-z]{10}/</code> 提取 BV 号，失败再试 av 号。<code>?p=N</code> 与 <code>page</code> 参数解析分 P，<code>cid</code> 从 <code>pages</code> 反查。</li><li><strong>匿名会话预热</strong>：无 Cookie 时先调 <code>x/frontend/finger/spi</code> 取 buvid3 / buvid4（设备指纹，30 分钟 TTL），否则部分匿名请求会被风控。</li><li><strong>VIP 状态与视频信息并行请求</strong>，省 1 个 RTT。VIP 判定缓存 5 分钟，视频信息缓存 2 分钟。</li><li>playurl 优先走 WBI 签名端点（签名 key 缓存 30 分钟）；失败且不属权限错误时降级到未签名端点。</li><li>结果以 <strong>NDJSON 流式响应</strong>逐行输出，前端边收边渲染进度。</li></ol><h3 id="ndjson-流式协议" tabindex="-1">NDJSON 流式协议 <a class="header-anchor" href="#ndjson-流式协议" aria-label="Permalink to &quot;NDJSON 流式协议&quot;">​</a></h3><p>响应头为 <code>Content-Type: application/x-ndjson</code> 与 <code>X-Accel-Buffering: no</code>；不设 <code>Connection</code> / <code>Transfer-Encoding</code>（hop-by-hop 头经反代会冲突）。每行写完立即 <code>flush()</code>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{&quot;status&quot;:&quot;parsing&quot;,&quot;step&quot;:&quot;info&quot;,&quot;message&quot;:&quot;正在解析视频信息...&quot;}</span></span>\n<span class="line"><span>{&quot;status&quot;:&quot;parsing&quot;,&quot;step&quot;:&quot;playurl&quot;,&quot;message&quot;:&quot;获取播放地址...&quot;}</span></span>\n<span class="line"><span>{&quot;success&quot;:true,&quot;status&quot;:&quot;done&quot;,&quot;videoUrl&quot;:&quot;...&quot;,&quot;audioUrl&quot;:&quot;...&quot;,&quot;format&quot;:&quot;dash&quot;,&quot;currentQn&quot;:80,...}</span></span>\n<span class="line"><span>{&quot;success&quot;:false,&quot;status&quot;:&quot;error&quot;,&quot;message&quot;:&quot;...&quot;,&quot;code&quot;:&quot;NO_PERMISSION&quot;}</span></span></code></pre></div><ul><li>进度 step 依次为 <code>vip</code> → <code>info</code> → <code>playurl</code> → <code>quality</code> → <code>cdn</code> → <code>fallback</code> → <code>finish</code>。</li><li>错误码：<code>RESOLVE_FAILED / VIDEO_NOT_FOUND / NOT_LOGGED_IN / NO_PERMISSION / INFO_FAILED / INVALID_INPUT / MP4_NOT_AVAILABLE / CDN_UNREACHABLE / DASH_NOT_AVAILABLE / NO_PLAYURL</code>。</li><li>前端整体 30s 超时（AbortController），先全量 <code>res.text()</code> 再逐行 parse，以规避部分浏览器对流式响应报 <code>net::ERR_ABORTED</code>；同时兼容旧版纯 JSON。</li></ul><h3 id="清晰度与大会员" tabindex="-1">清晰度与大会员 <a class="header-anchor" href="#清晰度与大会员" aria-label="Permalink to &quot;清晰度与大会员&quot;">​</a></h3><table tabindex="0"><thead><tr><th>身份</th><th>默认清晰度</th><th>上限</th></tr></thead><tbody><tr><td>未登录</td><td>480P（qn=32）</td><td>480P</td></tr><tr><td>登录非会员</td><td>1080P（qn=80）</td><td>1080P（VIP 专属档被过滤）</td></tr><tr><td>大会员</td><td>4K（qn=120）</td><td>8K（qn=127，fnval 追加 2048）</td></tr></tbody></table><p>取不到目标档位时的降级规则：</p><ul><li><code>VIP_ONLY_QNS = [112, 116, 120, 125, 126, 127]</code>，对应 1080P+ / 1080P60 / 4K / HDR / 杜比 / 8K。</li><li>权限不足时 qn 降到 32 / 16 重试；请求的 qn 不在 acceptQuality 中时回退到最高可用档重新请求。</li><li>MP4 模式（fnval=1 + platform=html5）最高 720P，这是 B站服务端硬限制，与会员状态无关；1080P 以上全部依赖 DASH 分离流。MP4 降级参数带 <code>try_look=1</code>，返回无防盗链直链。</li></ul><h3 id="cdn-健康检查" tabindex="-1">CDN 健康检查 <a class="header-anchor" href="#cdn-健康检查" aria-label="Permalink to &quot;CDN 健康检查&quot;">​</a></h3><p>取到地址后先探活：对 baseUrl + backupUrl 并行发起 HEAD + <code>Range: bytes=0-0</code> 竞速，接受 <code>ok || 405</code>，单条超时 3.5s、整体兜底 4s。部分 CDN 对 HEAD 返回 403 但 GET 正常，此时回退原始 URL。<code>.mcdn.bilivideo.cn:8082</code> 的 P2P CDN 地址会移除端口改走 443。</p><p>B站 API 公共封装：Chrome 120 UA、<code>Referer/Origin: https://www.bilibili.com</code>、单请求 10s 超时，<strong>412 风控自动重试 3 次（1~2s 随机退避）</strong>。</p><h3 id="番剧与影视-pgc" tabindex="-1">番剧与影视（PGC） <a class="header-anchor" href="#番剧与影视-pgc" aria-label="Permalink to &quot;番剧与影视（PGC）&quot;">​</a></h3><p>ep / ss 链接走独立解析管线：</p><ul><li><strong>链接识别</strong>：<code>/bangumi/play/ep829609</code>、<code>/bangumi/play/ss45612</code> 显式路径直接命中；裸 <code>ep123</code> / <code>ss456</code> 仅在无 BV / av 上下文且紧邻字符不是字母数字时认定（避免 <code>step1</code>、<code>sleep2</code> 误匹配），BV / av 优先。</li><li><strong>整季分集</strong>：ep 号先换整季信息（<code>pgc/view/web/season</code>），返回全部分集的 ep_id、cid、badge 与权威时长；badge（<code>会员</code> / <code>限免</code> / 空）用于标注会员专享集；仅 status=2（已上线）可选。</li><li><strong>播放地址</strong>：走 <code>pgc/player/web/playurl</code>（SESSDATA 鉴权，无 WBI 签名）。dash / durl 结构与普通视频一致，仅载荷在顶层 <code>result</code>（普通视频在 <code>data</code>），归一化后共用下游处理。</li><li><strong>试看判定不依赖 timelength</strong>：会员集对非会员返回试看 MP4，且 API 把 timelength 虚报为完整时长，因此由解析结果显式标记，不做时长比对。</li><li><strong>错误归一</strong>：-403（付费 / 大会员）、-404（下架）、-10403（地区限制）统一转为解析错误码。</li><li><strong>防盗链</strong>：PGC 的 MP4 直链强制 B站 Referer，由服务器代理转发，不走浏览器直连。</li></ul><h3 id="解析身份与默认模式" tabindex="-1">解析身份与默认模式 <a class="header-anchor" href="#解析身份与默认模式" aria-label="Permalink to &quot;解析身份与默认模式&quot;">​</a></h3><ul><li><strong>锚定房主 Cookie</strong>：服务器侧解析默认以影片所属房间<strong>房主的 B站 Cookie 身份</strong>执行，房主为大会员时会员内容全房间可拿完整地址，观众身份不参与服务器解析（见 <a href="/advanced/cli-protocol">CLI 代理协议</a>）。多 P 视频切分 P 后解析显式携带 page，缓存 key 含 page 维度。</li><li><strong>影片级「仅允许CLI模式」</strong>：番剧 / 影视可开启 cliOnly——成员必须连接本机 ZViewer CLI 观看，媒体流不经服务器，服务器仅承担同步信令；CLI 未连接时给出安装引导，不回退服务器转发。解析请求本身仍走服务器。</li><li><strong>默认解析参数</strong>（管理端基础设置）：普通视频 <code>bilibiliDefaultParseMode</code>（默认 mp4）；番剧影视 <code>bilibiliPgcDefaultMode</code>（默认 mp4）。影片未显式配置时按此回落。</li></ul><h2 id="代理层-api-stream-proxy" tabindex="-1">代理层 <code>/api/stream/proxy*</code> <a class="header-anchor" href="#代理层-api-stream-proxy" aria-label="Permalink to &quot;代理层 `/api/stream/proxy*`&quot;">​</a></h2><p>浏览器直连 B站媒体会被防盗链与 CORS 挡住，代理层由 <code>ProxyHTTPUpstream</code>（<code>internal/proxy/upstream.go</code>）统一实现：</p><ul><li><strong>域名白名单</strong>：媒体代理只放行 <code>bilibili.com / bilivideo.com / hdslb.com / biliimg.com / bstatic.com</code> 等后缀匹配，加 akamaized 精确项（共享 CDN 不能按后缀放行，否则会给第三方域名错误注入 B站 Referer）；图片代理只放行 4 个 B站图床域名。</li><li><strong>防盗链头</strong>：B站 URL 注入 <code>Referer/Origin</code> 加 Chrome UA；非 B站 URL 不注入。</li><li><strong>Range 有界分片</strong>：开放式 <code>bytes=0-</code> 与超长区间截断为有界分片；suffix（<code>bytes=-N</code>）与多段原样透传。上游 206 必须转发，透传 <code>content-length/content-range/accept-ranges/etag/last-modified</code> 并无条件补 <code>Accept-Ranges: bytes</code>；支持 <code>If-None-Match</code> / <code>If-Range</code> 走 304。</li><li><strong>断连销毁</strong>：客户端 <code>res.on(&#39;close&#39;)</code> 时 abort 上游 fetch 并显式 destroy 流（Node 的 pipe 不会自动销毁源流）。</li><li>上游 30s 超时只覆盖「连接 + 等响应头」，body 传输不中断；响应补 <code>X-Accel-Buffering: no</code> 禁用反代缓冲。</li><li><strong>前端路由决策中心</strong>（<code>url-proxy.ts</code> <code>resolveMediaRoute</code>）：本站 / blob / 相对路径直连；B站 DASH（<code>.m4s</code>）强制走服务器代理；B站 MP4 直链先直连、失败回退代理一次；HTTPS 页面下的 http 跨域源走代理（挂载直链模式跳过）；CLI 代理（127.0.0.1）属浏览器信任源，https 页面可直连。</li></ul><h2 id="直链实时解析-api-direct-resolve" tabindex="-1">直链实时解析 <code>/api/direct-resolve/*</code> <a class="header-anchor" href="#直链实时解析-api-direct-resolve" aria-label="Permalink to &quot;直链实时解析 `/api/direct-resolve/*`&quot;">​</a></h2><p>影片记录里的 url 只是添加时刻的快照，AList 签名会过期、源站协议也可能变化，因此播放时实时取一次新鲜直链，固化 URL 仅作兜底：</p><ul><li><strong>5 分钟 TTL 缓存</strong>（LRU，上限 500），key 为 <code>type|serverUrl|path</code>，可跨影片、跨房间共享。</li><li><strong>单飞去重</strong>：并发同 key 请求共享同一个 Promise，完成才写缓存，避免冷启动重复解析压垮源站。</li><li>优先走 AList API（许多用户把 AList 以 WebDAV 类型挂载，API 签名直链更可靠）；webdav 失败回退直链拼接（Basic Auth 内嵌）；openlist 失败直接报错不回退；ftp 无直链模式，固定走服务器代理。</li><li><strong>HTTPS 活性校验与自愈</strong>（<code>mount-utils.ts</code>）：缓存里的「该源支持 https 直链」是一次性探测结果，源站撤掉 TLS 后缓存地址永久不可达。因此下发前对 https 端点现场再探测（HEAD，5s 超时，2xx~5xx 均算成功），失败即把 <code>httpsDirect</code> 改写为 false 并<strong>持久化回写数据库</strong>，本次返回 http 直链。前端另有兜底：http 页面加载 https 直链失败时降级 http 重试一次。</li><li>Emby / Jellyfin：从 <code>/resolve</code> 实时取 MediaSources。音轨不在浏览器支持白名单（aac/mp3/flac/opus/vorbis）时自动切服务端转码 HLS（<code>main.m3u8?AudioCodec=aac...</code>），这类代理超时放宽到 90s（转码冷启动 30s 会被默认超时误杀）。</li></ul><h2 id="播放引擎" tabindex="-1">播放引擎 <a class="header-anchor" href="#播放引擎" aria-label="Permalink to &quot;播放引擎&quot;">​</a></h2><h3 id="引擎选择-engine-selector-ts" tabindex="-1">引擎选择（<code>engine-selector.ts</code>） <a class="header-anchor" href="#引擎选择-engine-selector-ts" aria-label="Permalink to &quot;引擎选择（`engine-selector.ts`）&quot;">​</a></h3><p>优先级：<code>format===&#39;dash&#39; || audioUrl</code> → <strong>videojs10-dash</strong>（video.js 10 作状态层，dash.js 5.2.0 作执行层，自研 MPD 构建包装 m4s）→ <code>hls</code> → <code>flv</code> → <code>shouldUsePlaysVideo()</code> 为真时用 <strong>playsvideo</strong> → 否则 <strong>videojs10</strong>（直链引擎，<code>selectDirectEngine()</code>；localStorage 设 <code>zviewer-vjs10-engine = &#39;0&#39;</code> 可回落经典 direct 引擎）。</p><table tabindex="0"><thead><tr><th>场景</th><th>引擎</th><th>判定</th></tr></thead><tbody><tr><td>MP4 / WebM / MOV</td><td>videojs10</td><td>原生可播，30s metadata 超时</td></tr><tr><td>AVI / TS / WMV</td><td>playsvideo</td><td>浏览器无法原生打开，必须重封装</td></tr><tr><td>MKV</td><td>playsvideo</td><td>原生支持仅限 H.264/AAC，DTS/AC3 音轨需转码</td></tr><tr><td>DTS / AC3 / EAC3 / TrueHD 音轨</td><td>playsvideo</td><td><code>needsBrowserTranscode</code> 判定，浏览器端转 AAC</td></tr></tbody></table><p>playsvideo 的唯一门控是影片级「浏览器转码引擎」开关（<code>playsvideoEnabled</code>）：关闭即强制原生直连，原生失败不回退；未设置时只要浏览器具备 MSE + Worker 即按上表生效。</p><ul><li><strong>playsvideo 管线</strong>：mediabunny 流式 demux（Range 随机读取）→ 关键帧对齐分段 → 视频直通重封装或音频按需转码（AC3/EAC3/DTS/FLAC/MP3/Opus → AAC）→ fMP4 分段 + m3u8 → hls.js 按段拉取。取流 URL <strong>必须同源</strong>，跨域一律包装 <code>/api/stream/proxy?url=</code>。准备超时 60s。</li><li><strong>服务器零依赖</strong>：转码核心随前端资源分发（专用 ffmpeg 构建约 1.9MB）。</li><li><strong>attach 互斥与世代模型</strong>（<code>usePlayerSource.ts</code>）：attach 走串行队列，用 <code>attachEpochRef</code> 做世代计数；一次 attach 在 await 期间被新加载取代时静默退出，消除假超时。另有 video 级会话登记表（WeakMap，后发起者赢），避免跨实例并发 attach 到同一 video 造成双声。401/403 时自动 <code>refreshAccessToken()</code> 后重试一次。</li></ul><h2 id="字幕" tabindex="-1">字幕 <a class="header-anchor" href="#字幕" aria-label="Permalink to &quot;字幕&quot;">​</a></h2><h3 id="内嵌字幕提取-mkv" tabindex="-1">内嵌字幕提取（MKV） <a class="header-anchor" href="#内嵌字幕提取-mkv" aria-label="Permalink to &quot;内嵌字幕提取（MKV）&quot;">​</a></h3><p>自研 <code>MatroskaDemuxer</code> 做流式解复用（<code>lib/mkv/</code>），未使用 ffmpeg.wasm（需整文件载入，上限约 2GB）。</p><ul><li>先做头部 4MB Range 预取收齐 Tracks。≤512MB 全量顺序扫描；更大文件走<strong>稀疏提取</strong>：Cues 锚点分段、按元素 size 链前进、音视频负载按字节算术跳过，5GB 级片源只需传约 10% 字节。稀疏窗口 64KB（12 并发会使代理失效，限 2 并发），worker 按「距当前播放位置最近」选锚点（seek 感知）。</li><li>支持文本轨 SRT/ASS/SSA/WEBVTT；PGS 位图轨由 <code>pgs-decoder.ts</code> 解码调色板 RLE 位图后按时间轴渲染为图片；VOBSUB 仍不支持。</li><li>Emby/Jellyfin 内嵌字幕走后端 <code>/embedded-tracks</code> + <code>/embedded-extract</code>。外挂字幕搜索覆盖 webdav/openlist/ftp/server-files，文件上限 2MB。</li></ul><h3 id="b站-ai-字幕" tabindex="-1">B站 AI 字幕 <a class="header-anchor" href="#b站-ai-字幕" aria-label="Permalink to &quot;B站 AI 字幕&quot;">​</a></h3><p><code>x/player/v2</code> 不稳定：同一 (bvid, cid) 会<strong>随机返回其他视频的字幕</strong>，且字幕 JSON 内没有视频标识。后端 <code>/api/stream/bilibili/ai-subtitle</code> 设了三重防线：</p><ol><li><strong>带外校验</strong>：subtitle_url 的 <code>oid</code> 必须等于 aid。</li><li><strong>带内校验</strong>：时间轴终点须约等于时长，容差 <code>max(10s, 时长 × 8%)</code>。前端必须传 <code>&amp;duration=</code>（秒），非法时用官方时长兜底。</li><li><strong>一致性投票</strong>：最多 6 次（间隔 180ms），按内容指纹（<code>len:首行:末行to</code>）投票，两次一致即确认；全部不达标返回空。成功缓存 10 分钟，失败负缓存 60s。</li></ol><h2 id="弹幕" tabindex="-1">弹幕 <a class="header-anchor" href="#弹幕" aria-label="Permalink to &quot;弹幕&quot;">​</a></h2><ul><li><strong>B站官方 XML</strong>：<code>x/v1/dm/list.so?oid=&lt;cid&gt;</code>，正则解析 <code>&lt;d p=&quot;...&quot;&gt;</code> 属性段（time/mode/size/color…），XML 实体手动反转义；前端按 mode 映射滚动 / 顶部 / 底部轨道。</li><li><strong>第三方聚合</strong>：provider 注册表含 bilibili-video / bilibili-bangumi / 巴哈姆特 / 弹弹play。搜索时把关键词生成「原文 + 繁体 + 简体」三变体并行请求再去重排序；<code>/fetch</code> 的 <code>playbackParams</code> 必须原样回传（弹弹play 缺 episodeId 会报错）。</li><li><strong>渲染</strong>（<code>danmakuEngine.ts</code>，基于 danmaku 库）：字号 = 用户基准 × B站 size 比例 × 屏幕比例（0.5~1.5 自适应）。屏蔽支持关键词与类型（滚动 / 固定 / 高级 / 彩色）两个维度，变更后清空重载。实时弹幕与屏蔽词经 Socket 跨端同步（<code>RoomDanmakuMeta</code>）。</li><li><strong>本地导入</strong>（<code>localImport.ts</code>，纯前端解析）：支持 B站 XML / B站 JSON / dandanplay JSON，解析结果作为独立弹幕轨道挂载，不经服务器。</li></ul><h2 id="obs-推流与-b站下载" tabindex="-1">OBS 推流与 B站下载 <a class="header-anchor" href="#obs-推流与-b站下载" aria-label="Permalink to &quot;OBS 推流与 B站下载&quot;">​</a></h2><ul><li><strong>内置媒体服务</strong>（<code>internal/nms</code>，进程内 Go 实现）：RTMP 监听 3334，HTTP-FLV 监听 3335，由 <code>/live</code> 反代。<code>STREAM_PUSH_ENABLED=0</code> 时完全不启动，3334/3335 不监听。推流码在发布时校验：路径为 <code>/live/&lt;streamKey&gt;</code>，且房间 active、投屏模式、stream-push 子模式。推流与断流广播 <code>stream-status {live|offline}</code>，DB 查询失败也不漏广播（活跃会话兜底）。</li><li><strong>OBS 配置一键下载</strong>：<code>GET /api/stream-push/obs-config/:roomId</code> 生成场景集合 JSON（rtmp_custom），无 streamKey 时自动生成。</li><li><strong>server-files B站下载</strong>（仅 root）：走 <code>preferMp4 + skipCdnCheck</code>。DASH 分离流需服务器 FFmpeg 合并，而 FFmpeg 已移除；B站 MP4 接口硬限 720P，因此高画质下载需走 CLI 模式。进度以 NDJSON 输出（每 2% 或 512KB），失败自动清理不完整文件，VIP 档位做服务端强校验。</li></ul><h2 id="关键常量速查" tabindex="-1">关键常量速查 <a class="header-anchor" href="#关键常量速查" aria-label="Permalink to &quot;关键常量速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>常量</th><th>值</th></tr></thead><tbody><tr><td>MP4 直链清晰度上限</td><td>720P（qn=64，B站硬限制）</td></tr><tr><td>B站单请求超时 / 412 重试</td><td>10s / 3 次（1~2s 退避）</td></tr><tr><td>CDN 健康检查</td><td>3.5s 单条 / 4s 兜底</td></tr><tr><td>直链解析缓存 / https 探测</td><td>5min（LRU 500）/ 5s</td></tr><tr><td>代理上游超时</td><td>30s（仅连接 + 响应头阶段）</td></tr><tr><td>direct 引擎 metadata / playsvideo 准备超时</td><td>30s / 60s</td></tr><tr><td>MKV 提取</td><td>头部 4MB / 全量 ≤512MB / 稀疏窗口 64KB / 并发 2</td></tr><tr><td>AI 字幕</td><td>6 次尝试 / 容差 max(10s, 8%) / 成功缓存 10min</td></tr><tr><td>FLV 追帧</td><td>max 1.5s / target 0.5s</td></tr></tbody></table>',47)])])}const g=o(i,[["render",s]]);export{h as __pageData,g as default};
